{"cards": [{"node_code": "N_7fdcee38716548bd", "definition": "研究气体或液体作为连续相，固体颗粒作为离散相共存时的流动机理、相互作用及宏观行为。", "boundary": "聚焦于气固、液固两相体系，涵盖颗粒沉降、悬浮、团聚及颗粒-流体动量/能量交换。与“流化床、旋风与颗粒输运”的区别在于：本节点侧重基础流动规律、颗粒动力学及微观相互作用；若侧重特定工程设备（如流化床反应器、旋风分离器）的运行特性或整体输运过程，归入兄弟节点。", "includes": ["气固、液固两相流的基本流动规律与颗粒动力学", "颗粒-流体相互作用、曳力模型及颗粒团聚/分散机制", "稀相、密相颗粒流的宏观行为及数值模拟基础"], "excludes": ["以流化床、旋风分离器等具体设备设计与运行为核心的研究（归入流化床、旋风与颗粒输运）", "不含固体颗粒的气液/液液界面流动（归入气液与液液两相流）"], "sibling_distinctions": [{"other_code": "N_cf9b3dec98c63cf8", "rule": "本节点侧重颗粒流的基础机理、颗粒动力学及微观相互作用；兄弟节点侧重流化床、旋风分离器等具体工程设备中的颗粒输运与分离过程。"}], "cross_boundary_rule": ""}, {"node_code": "N_cf9b3dec98c63cf8", "definition": "研究颗粒在特定工程设备或系统中的宏观输运、分离及流化行为，涵盖流化床、旋风分离及管道输送。", "boundary": "聚焦于颗粒流在工程装置中的应用，包括流化床的水力学特性、旋风分离器的分离效率及颗粒在管道/槽道中的连续输运。与“气固与液固颗粒流”的区别在于：本节点侧重设备级或系统级的宏观过程与工程应用；若侧重颗粒-流体微观相互作用或基础流动规律，归入兄弟节点。", "includes": ["流化床的水力学特性、流化状态及工程应用", "旋风分离器、静电除尘等颗粒分离设备原理", "颗粒在管道、槽道中的连续输运与磨损特性"], "excludes": ["颗粒-流体微观相互作用、曳力模型等基础机理研究（归入气固与液固颗粒流）", "不含颗粒的纯流体分离或输送（归入流体力学）"], "sibling_distinctions": [{"other_code": "N_7fdcee38716548bd", "rule": "本节点侧重流化床、旋风分离器等具体工程设备中的颗粒输运与分离过程；兄弟节点侧重颗粒流的基础机理、颗粒动力学及微观相互作用。"}], "cross_boundary_rule": ""}, {"node_code": "N_5b06900db5f024d1", "definition": "研究流体在多孔介质骨架中的渗透规律，以及具有非牛顿流变学特性流体的流动行为。", "boundary": "聚焦于连续相为多孔介质（如岩石、土壤、过滤材料）或流体本身具有剪切变稀/增稠、触变等非牛顿特性的流动。与“气固与液固颗粒流”的区别在于：本节点中固体以固定骨架形式存在或流体本身性质复杂，而非离散颗粒在连续相中运动；若涉及颗粒在多孔介质中的迁移，需结合颗粒流节点。", "includes": ["多孔介质中的达西/非达西流动及渗透率研究", "非牛顿流体（聚合物溶液、泥浆、血液等）的流变学特性", "复杂流体在微通道、生物组织或工业过滤中的流动行为"], "excludes": ["离散固体颗粒在连续流体中的运动与相互作用（归入气固与液固颗粒流）", "单相牛顿流体在简单几何中的基本流动（归入流体力学）"], "sibling_distinctions": [{"other_code": "N_7fdcee38716548bd", "rule": "本节点处理固体以固定骨架形式存在（多孔介质）或流体本身具有非牛顿特性的流动；兄弟节点处理离散固体颗粒在连续流体中的运动与相互作用。"}], "cross_boundary_rule": ""}]}
